const d = $input.first().json;
const wfName = (d.workflow && d.workflow.name) || 'Unknown workflow';
const wfId = (d.workflow && d.workflow.id) || '';
const execId = (d.execution && d.execution.id) || '';
const errMsg = (d.execution && d.execution.error && d.execution.error.message) || 'No message';
const lastNode = (d.execution && d.execution.lastNodeExecuted) || 'Unknown node';
const execUrl = (d.execution && d.execution.url) || ('https://n8n-trading-project.onrender.com/workflow/' + wfId + '/executions/' + execId);
const now = new Date().toISOString();
const html = '<html><body style="font-family:Arial,sans-serif;font-size:14px;">' +
  '<h2 style="color:#c0392b;">⚠️ Trading Agent - Workflow Error</h2>' +
  '<table border="1" cellpadding="6" cellspacing="0">' +
  '<tr><td>Time (UTC)</td><td>' + now + '</td></tr>' +
  '<tr><td>Workflow</td><td>' + wfName + '</td></tr>' +
  '<tr><td>Failed Node</td><td>' + lastNode + '</td></tr>' +
  '<tr><td>Error Message</td><td>' + errMsg + '</td></tr>' +
  '</table>' +
  '<p><a href="' + execUrl + '">View full execution details in n8n</a></p>' +
  '<p style="color:#777;font-size:12px;">No real BingX funds are at risk from this specific error - live execution is not yet enabled.</p>' +
  '</body></html>';
return [{ json: { html: html, wfName: wfName, errMsg: errMsg } }];
